import java.util.*;

public class SafeTreeSet {
    record Order(String id, double price) {}

    public static NavigableSet<Order> build() {
        Comparator<Order> comp = Comparator
            .comparingDouble(Order::price)
            .thenComparing(Order::id);
        return new TreeSet<>(comp);
    }
}

