import java.util.*;

public class SafeRemoval {
    public static void clean(List<String> items) {
        Iterator<String> it = items.iterator();
        while (it.hasNext()) {
            if (it.next().equals("B")) it.remove();
        }
        items.removeIf(item -> item.equals("C"));
    }
}

